# frozen_string_literal: true

require 'active_support/core_ext/string/inflections'
require 'graphql'

module GraphQL
  module Derivation
    module Rails
      # SPEC.md §8.2. A minimal per-namespace `GraphQL::Schema` subclass. It
      # exists only to:
      #
      #   1. Hold every anonymous InputObject generated by the ControllerConcern
      #      so they are introspectable (for TypeScript codegen) without
      #      polluting the application schema.
      #   2. Provide the query context used to coerce request input
      #      (`coerce_input` reads argument visibility through a context).
      #
      # graphql-ruby `GraphQL::Schema` subclasses are used as singletons via
      # class methods (`MySchema.execute(...)`, never `MySchema.new`), so
      # `.for(namespace)` returns/caches a *subclass* per namespace, not an
      # instance. The cache lives on `ArgumentSchema` itself, keyed by namespace.
      #
      # ## Introspection design (see `to_definition`/`build_print_schema`)
      #
      # `self` (the cached `ArgumentSchema.for(namespace)` instance) never
      # gets a real query root, and is never used with `extra_types`/
      # `orphan_types` either -- `to_definition` is overridden to delegate
      # printing to a fresh, disposable schema built on every call, which
      # *does* get a real (synthetic, never executed) query root. See
      # `build_print_schema`'s docs for why a real root is necessary at all
      # (an `extra_types`-only design cannot make a nested-InputObject
      # argument reachable, which matters for `resource_arguments`,
      # SPEC.md §8.1) and why it must be a fresh disposable schema rather
      # than something set once on `self`.
      class ArgumentSchema < GraphQL::Schema
        # SPEC.md §8.2 "graphql-ruby version compatibility": `GraphQL::Query::
        # NullContext` cannot be used here on ANY graphql-ruby version this
        # gem supports (>= 2.1, SPEC.md §1.2) -- through at least 2.5.x it
        # remains a true `Singleton` (private `.new`) fixed to its own
        # internal `NullSchema`, so it can never be bound to *this*
        # `ArgumentSchema`. `NullQueryContext` is this gem's own permanent
        # replacement, not a version-conditional shim: built from the same
        # primitives graphql-ruby's own `NullContext` composes internally
        # across that whole range (`GraphQL::Schema::Warden::NullWarden`,
        # `GraphQL::Dataloader::NullDataloader`), bound to the schema that's
        # actually passed in.
        class NullQueryContext
          # Duck-typed stand-in for `GraphQL::Query`. `InputObject#coerce_input`
          # calls `context.query.after_lazy(value) { ... }` on every
          # graphql-ruby version in range, always with a value already
          # resolved synchronously by `NullWarden`/`NullDataloader` below --
          # there is never anything to actually wait on. This mirrors
          # graphql-ruby's own (private) `NullContext::NullQuery`, which
          # behaves identically -- no genuine lazy resolution -- on every
          # version in range.
          class NullQuery
            def after_lazy(value)
              yield(value)
            end
          end

          attr_reader :schema, :query, :warden, :dataloader

          def initialize(schema:)
            @schema = schema
            @query = NullQuery.new
            @dataloader = GraphQL::Dataloader::NullDataloader.new
            @warden = GraphQL::Schema::Warden::NullWarden.new(context: self, schema: schema)
          end

          # `InputObject#coerce_arguments` reads argument visibility via
          # `context.types.arguments(...)` on graphql-ruby >= 2.4, and via
          # `context.warden.arguments(...)` (see `#warden` above) on 2.1.x
          # through 2.3.x, which never calls `#types` at all. Delegates to
          # `warden.visibility_profile`, which only exists on the
          # graphql-ruby releases that actually call `#types` -- so this is
          # never invoked against a `warden` that lacks it.
          def types
            warden.visibility_profile
          end

          # `GraphQL::Query::Context`'s scoped-storage interface (`ctx[:foo]`),
          # matching `NullContext`'s own delegate-to-an-empty-hash behaviour on
          # every graphql-ruby version in range.
          def [](_key)
            nil
          end

          def fetch(_key, default = nil)
            default
          end

          def dig(*_keys)
            nil
          end

          def key?(_key)
            false
          end

          def to_h
            {}
          end
        end

        # Class-level behaviour mixed into each per-namespace ArgumentSchema
        # subclass. Extracted into a module so `build_namespace_schema` stays a
        # thin factory.
        module NamespaceSchema
          attr_reader :argument_namespace

          # Registers a *top-level* (action-level) anonymous InputObject so it
          # (and everything it references, at any depth) shows up in this
          # schema's SDL for codegen. Do not call this for a
          # `resource_arguments` scope's own nested InputObject -- it becomes
          # reachable automatically once the outer one is (see the class doc
          # above); registering it too would be harmless but redundant.
          #
          # De-duplicates by `graphql_name`, not object identity. Rails class
          # reloading (Zeitwerk) rebuilds `ControllerConcern`'s anonymous
          # InputObject as a brand-new class object on every reload, but with
          # the SAME computed `graphql_name` (derived from the stable
          # controller/action names). This schema is cached for the process
          # lifetime (`ArgumentSchema.for`), so without name-based dedup, each
          # reload would append a second class with the same `graphql_name` to
          # `registered_input_objects` -- and since the query root is fully
          # rebuilt from `registered_input_objects` on every call (see
          # `rebuild_query_root!`), a stale duplicate would linger forever and
          # raise `GraphQL::Schema::DuplicateNamesError` on the next
          # `to_definition`/validation/introspection call.
          #
          # Behaviour: registering a never-seen `graphql_name` appends as
          # before. Registering a `graphql_name` that is already present
          # REPLACES the existing entry with the new class object -- this is
          # what makes a reload-driven redefinition safe. Registering the
          # exact same object twice is therefore also safe: it replaces
          # itself, a no-op in effect. Either way, the list ends up with
          # exactly one entry per `graphql_name`, always the most recently
          # registered class.
          def register_input_object(input_object_class)
            registered_input_objects.reject! { |existing| existing.graphql_name == input_object_class.graphql_name }
            registered_input_objects << input_object_class
          end

          def registered_input_objects
            @registered_input_objects ||= []
          end

          # The query context used to coerce request input. A `NullWarden`
          # -backed context bound to this schema gives all-types-visible
          # semantics, exactly SPEC.md §8.2's requirement, on every
          # graphql-ruby version this gem supports (see `NullQueryContext`).
          def coercion_context
            NullQueryContext.new(schema: self)
          end

          # Delegates to a disposable, print-only schema instead of printing
          # `self` directly -- see `build_print_schema` for why. `self`
          # (the cached `ArgumentSchema.for(namespace)` instance) never gets
          # a `query` root at all; only this throwaway one does. Falls back
          # to `super` (printing `self`, with no root) when nothing has
          # been registered yet -- a query root with zero fields would just
          # trigger graphql-ruby's own "Object types must have fields"
          # warning for no benefit.
          def to_definition(**kwargs)
            return super if registered_input_objects.empty?

            build_print_schema.to_definition(**kwargs)
          end

          private

          # A fresh, disposable `GraphQL::Schema` built solely so
          # `to_definition` has something to print -- never cached, never
          # returned from `ArgumentSchema.for`, and never used for
          # `coercion_context` (which doesn't need a query root at all,
          # `NullWarden` ignores reachability entirely).
          #
          # Why a *real* query root, not `extra_types`/`orphan_types`: an
          # InputObject with no real root is entirely unreachable, so it
          # (and everything it references) is invisible to `to_definition`.
          # `extra_types` looked like the right tool, but graphql-ruby's own
          # SDL printer has a structural gap for it: to compute reachability
          # for `extra_types` entries, it builds a synthetic query type with
          # one field per entry -- but explicitly skips InputObject-kind
          # entries when doing so, since GraphQL forbids InputObject as a
          # field *return* type. An `extra_types`-registered InputObject is
          # therefore always printed itself, but any of its own arguments
          # whose *type* is also an InputObject (exactly the
          # `resource_arguments` case, SPEC.md §8.1) can never be reached
          # this way, regardless of what else is added to `extra_types` --
          # confirmed with a minimal graphql-ruby-only repro, no
          # `ArgumentSchema` involved.
          #
          # The fix: a real (synthetic, never actually executed -- nothing
          # ever calls `.execute` on this) `query` root, with one field per
          # registered top-level InputObject, each exposing that InputObject
          # as a field *argument* (arguments, unlike fields, may be
          # InputObject-typed). Once the top-level InputObject is reachable
          # via a real root, graphql-ruby's normal reachability traversal
          # correctly walks everything it references, at any nesting depth,
          # with no special-casing needed here at all -- this is why only
          # top-level InputObjects need registering (`register_input_object`
          # above); a `resource_arguments` scope's own nested InputObject is
          # reached automatically as soon as the outer one is.
          #
          # Why a fresh disposable schema class per call, rather than
          # setting `@query_object` once on `self` and reusing it:
          # `Schema.query(new_root)` (the inherited setter) raises if called
          # more than once per schema class ("Second definition of
          # `query(...)`"), but `register_input_object` fires many times
          # over `self`'s process-lifetime cache (`ArgumentSchema.for`), once
          # per controller action -- so `self` can never safely call its own
          # `query` setter more than once. Setting `@query_object` directly
          # (bypassing the guarded setter) was tried and confirmed broken
          # empirically: the setter's `add_type_and_traverse(@query_object,
          # root: true)` side effect turned out to be required bookkeeping
          # for reachability, not just a one-time guard -- skipping it
          # silently dropped the query root's own arguments from the
          # printed SDL. A fresh schema class, built fresh on every call,
          # sidesteps both problems: it calls the real setter, and it only
          # ever calls it once (being a brand new class each time).
          def build_print_schema
            dummy_query = build_dummy_query_type
            Class.new(GraphQL::Schema) { query(dummy_query) }
          end

          # One field per registered top-level InputObject, each exposing
          # that InputObject as a field argument -- see `build_print_schema`
          # for why.
          def build_dummy_query_type
            query_type_name = sanitized_graphql_name("#{argument_namespace}ArgumentSchemaQuery")
            query_type = Class.new(GraphQL::Schema::Object) { graphql_name query_type_name }
            registered_input_objects.each { |type| add_argument_carrying_field(query_type, type) }
            query_type
          end

          def add_argument_carrying_field(query_type, input_object_class)
            field_name = input_object_class.graphql_name.underscore
            query_type.field(field_name, GraphQL::Types::Boolean, null: true) do
              argument :input, input_object_class, required: false
            end
          end

          # `argument_namespace` may be an arbitrary Symbol/String; this
          # dummy type's name only needs to be *a* valid GraphQL name, not a
          # meaningful one -- it is never printed anywhere a human reads it
          # as anything but an implementation detail.
          def sanitized_graphql_name(name)
            name.gsub(/[^a-zA-Z0-9_]/, '_').sub(/\A[0-9]/, '_\0')
          end
        end

        class << self
          # Returns (creating and caching on first use) the schema subclass for
          # +namespace+. One subclass per namespace, cached for the process
          # lifetime. `nil` collapses to the default namespace `:default`
          # (SPEC.md §8.2).
          def for(namespace)
            namespace ||= :default
            schemas[namespace] ||= build_namespace_schema(namespace)
          end

          # Test/introspection seam: forget all cached per-namespace schemas.
          # Not part of the public runtime API -- used to keep specs isolated.
          def reset!
            @schemas = {}
          end

          private

          def schemas
            @schemas ||= {}
          end

          def build_namespace_schema(namespace)
            schema = Class.new(self)
            schema.extend(NamespaceSchema)
            schema.instance_variable_set(:@argument_namespace, namespace)
            schema
          end
        end
      end
    end
  end
end
